from pathlib import Path
import os,sys,datetime,itertools,json
os.environ['CUDA_VISIBLE_DEVICES']=''
from round031_study_core import R,read,write,sha,verify

def main():
 assert not (R/'experiment-plan.json').exists() and not list(R.glob('*-job.json'));a=read(R/'integration-cpu-audit.json');assert a['passed'] and a['CPU_only'] and a['full_denied_proposals_retained'] and a['model_predictions']==0
 integration=read(R/'native-loop-integration-audit.json');assert integration['native_run_exactly_recovered_after_removing_five_hooks'] and sha('scripts/round031_native_loop.py')==integration['hooked_loop_sha256'];assert sha('scripts/request_execution_guard.py')=='c6e5efe26653bd887ce6a4c897dcc9626f5911e494ebb530ccb8c1bc9acb403d'
 old=read(R.parent/'round-029-2026-10-09/experiment-plan.json');files=old['sha256'].copy()
 for f,h in files.items():assert sha(f)==h,f
 prep=read(R/'fresh-preparation-plan.json');res=read(R/'fresh-preparation-result.json');assert prep['families']==res['families']==['FCAS','FCSA'] and res['gold_passed']==32 and res['full_program_overlap_previous']==0
 for f,h in {**prep['sha256'],**res['sha256']}.items():assert sha(f)==h
 sys.path[:0]=['AgenticArxiv','scripts'];from benchmark.metrics import extract_metrics,is_strict_success
 from prepare_round031_confirmation import signature
 from request_execution_guard import RequestExecutionGuard
 gold=[json.loads(x) for x in (R/'fresh-gold-traces.jsonl').read_text().splitlines()];oracles={t['id']:t for g in ['freshA','freshB'] for t in read(R/(g+'-oracles.json'))};assert len(gold)==len(oracles)==32
 previous=[]
 for f in prep['sha256']:
  if f.endswith('oracles.json') or f.endswith('all-tasks.json'):previous+=read(f)
 excluded={tuple(t['expected_tools']) for t in previous};chosen=[f for f in sorted(''.join(x) for x in itertools.permutations('CSFA') if x.index('F')<x.index('A')) if tuple(signature(f)) not in excluded][:2];assert chosen==prep['families']
 for x in gold:
  t=oracles[x['task_id']];m=extract_metrics(t,{'history':x['history']},'CPUindependent',0,x['task_id']);assert is_strict_success(m) and not m.false_finish;guard=RequestExecutionGuard(t['task']);assert [s.name for s in guard.steps]==t['expected_tools']
 groups={k:old['groups'][k] for k in ['olddev','newdev']};groups.update(seenA=old['groups']['freshA'],seenB=old['groups']['freshB'])
 for g,w in [('freshA','trainA'),('freshB','trainB')]:groups[g]={'tasks':str(R/(g+'-oracles.json')),'oracles':str(R/(g+'-oracles.json')),'split':str(R/'fresh-split.json')+':'+g,'snapshot':'data/repro_round024/'+w+'-snapshot.json'}
 sizes={g:len(read(v['split'].rsplit(':',1)[0])['split'][v['split'].rsplit(':',1)[1]])*3 for g,v in groups.items()};assert list(sizes.values())==[24,48,48,48,48,48] and sum(sizes.values())*4*2==2112
 sources=['round031_guard_agent.py','round031_native_loop.py','run_round031_eval.py','build_round031_loop.py','audit_round031_integration.py','prepare_round031_confirmation.py','round031_study_core.py','run_round031_study.py','finalize_round031_study.py','register_round031_study.py','launch_round031_study.py','run_round020_gpu_job.py','run_round027_retention.py','request_execution_guard.py']
 for f in [Path('scripts')/s for s in sources]+[Path('AgenticArxiv/agents/base_agent.py'),Path('AgenticArxiv/agents/agent_engine.py'),Path('AgenticArxiv/benchmark/runner.py')]+[f for f in R.iterdir() if f.is_file()]:files[str(f)]=sha(f)
 for g in groups.values():
  for k in ['tasks','oracles','snapshot']:files[g[k]]=sha(g[k])
  f=g['split'].rsplit(':',1)[0];files[f]=sha(f)
 freeze={'recorded_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_model':old['source_model'],'sha256':{str(f):sha(f) for f in Path(old['source_model']).rglob('*') if f.is_file()},'new_weight_updates':0}
 rules={'fresh_execution_gain3_vs_native_budget':'Every seed AND freshA/B execution strict guard >= max(native,budget)+3/48','fresh_execution_no_worse_state':'Every seed AND freshA/B execution strict guard >= state; veto incremental benefit requires separate state-to-guard comparison','all_proposal_strict_no_worse_budget':'Every seed AND all six groups full proposal strict guard >= budget','olddev_proposal_no_worse_native':'Every seed olddev full proposal strict guard >= native','all_execution_FF_no_worse_budget_state':'Every seed AND all six groups execution FF guard <= min(budget,state)','fresh_total_tokens_at_most1_5x_budget':'Every seed AND each fresh world total prompt+completion tokens guard <=1.5*budget, including all denials'}
 p={'registered_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'question':'Can instruction-compiled state hints and pre-execution checks improve retained-SFT Agent execution beyond extra-budget and state-only controls without hiding model errors or excessive token costs?','learning_permitted':False,'source_model':old['source_model'],'source_model_freeze':freeze,'modes':['native','budget','state','guard'],'generation_seeds':[45,46],'repeat':3,'groups':groups,'group_trial_runs':sizes,'inference_jobs':48,'total_trial_scores':2112,'historical_trials_reused':0,'comparisons':48,'comparison_pairs':[['native','budget'],['budget','state'],['state','guard'],['budget','guard']],'budget_policy':'native task max_iterations/default5; all others +4 model calls; denials consume calls; all calls max_tokens1000 temperature0.1 bf16','state_control':'same instruction-compiled next action hint as guard, no veto','unsupported_request_policy':'state/guard use unchanged native loop with extended +4 budget','primary_metric':'native original strict on full proposal history, including rejected proposals and their failed observations','secondary_metric':'same frozen scorer on execution-only history; architecture behavior, never substituted for model proposal quality','runtime_guard_input':'user instruction + actual structured tool results only; no task IDs/oracles/expected_tools','fresh_families':['FCAS','FCSA'],'scope':'Two full program families absent previous full sequences, shared tools/params/subsequences and two reused TRAIN paper worlds. Explicit Chinese request grammar compiler and next-action hint; not broad learned planning, paper-blind or statistically independent family generalization. Figure descriptions remain extractive.','success_rule':rules,'failure_closes_fixed_recipe':True,'no_automatic_promotion':True,'no_after_output_budget_prompt_case_or_seed_tuning':True,'allowed_physical_gpus':[4,7],'minimum_inference_free_mib':8192,'finite_controller_timeout_seconds':86400,'inference_job_timeout_seconds':3600,'GPU_capacity_wait_seconds':1800,'sha256':files}
 verify(p);write(R/'source-model-before-inference.json',freeze);write(R/'registration-independent-audit.json',{'passed':True,'checked_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'old1356_inputs_unchanged':len(old['sha256']),'fresh_gold_rescored':32,'fresh_families':chosen,'full_program_overlap_previous':0,'CPU_model_predictions':0,'budget_enumerated':{'seeds':2,'modes':4,'runs_per_seed_mode':264,'total':2112,'jobs':48,'comparisons':48},'native_core_and_scorer_unchanged':True});p['sha256'][str(R/'registration-independent-audit.json')]=sha(R/'registration-independent-audit.json');p['sha256'][str(R/'source-model-before-inference.json')]=sha(R/'source-model-before-inference.json');write(R/'experiment-plan.json',p);print({'registered_at_utc':p['registered_at_utc'],'trials':2112,'jobs':48,'new_learning':0,'families':chosen,'inputs':len(p['sha256'])})
if __name__=='__main__':main()
